export async function createSecretStore(
  options: SecretStoreOptions,
): Promise<SecretStore> {
  const { storage, masterPassword } = options;

  const SALT_KEY = "\x00__secretstore_salt__\x00";
  const CHECK_KEY = "\x00__secretstore_check__\x00";
  const SECRET_PREFIX = "\x00__secretstore_secret__\x00";

  const encoder = new TextEncoder();
  const decoder = new TextDecoder();

  function bytesToB64(bytes: Uint8Array): string {
    let binary = "";
    for (let i = 0; i < bytes.length; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  }

  function b64ToBytes(b64: string): Uint8Array {
    const binary = atob(b64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
  }

  function encodeStr(s: string): string {
    return bytesToB64(encoder.encode(s));
  }

  function decodeStr(s: string): string {
    return decoder.decode(b64ToBytes(s));
  }

  function makeKey(owner: string, name: string): string {
    return SECRET_PREFIX + encodeStr(owner) + "|" + encodeStr(name);
  }

  function makeAad(owner: string, name: string): Uint8Array {
    const ownerBytes = encoder.encode(owner);
    const nameBytes = encoder.encode(name);
    const aad = new Uint8Array(8 + ownerBytes.length + nameBytes.length);
    const view = new DataView(aad.buffer);
    view.setUint32(0, ownerBytes.length, true);
    view.setUint32(4, nameBytes.length, true);
    aad.set(ownerBytes, 8);
    aad.set(nameBytes, 8 + ownerBytes.length);
    return aad;
  }

  // Get or create salt
  let salt: Uint8Array;
  const existingSalt = await storage.get(SALT_KEY);
  if (existingSalt !== undefined) {
    salt = b64ToBytes(existingSalt);
  } else {
    salt = crypto.getRandomValues(new Uint8Array(16));
    await storage.set(SALT_KEY, bytesToB64(salt));
  }

  // Derive key
  const keyMaterial = await crypto.subtle.importKey(
    "raw",
    encoder.encode(masterPassword),
    "PBKDF2",
    false,
    ["deriveKey"]
  );

  const derivedKey = await crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt,
      iterations: 100000,
      hash: "SHA-256",
    },
    keyMaterial,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"]
  );

  // Verify or create check
  const existingCheck = await storage.get(CHECK_KEY);
  if (existingCheck !== undefined) {
    try {
      const checkData = b64ToBytes(existingCheck);
      if (checkData.length < 13) throw new Error("corrupt check");
      const iv = checkData.subarray(0, 12);
      const ct = checkData.subarray(12);
      await crypto.subtle.decrypt({ name: "AES-GCM", iv }, derivedKey, ct);
    } catch {
      throw new Error("Invalid master password");
    }
  } else if (existingSalt === undefined) {
    // Fresh store
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const ct = await crypto.subtle.encrypt(
      { name: "AES-GCM", iv },
      derivedKey,
      encoder.encode("__secretstore_check__")
    );
    const blob = new Uint8Array(12 + ct.byteLength);
    blob.set(iv, 0);
    blob.set(new Uint8Array(ct), 12);
    await storage.set(CHECK_KEY, bytesToB64(blob));
  }

  return {
    async put(owner: string, name: string, value: string) {
      const key = makeKey(owner, name);
      const iv = crypto.getRandomValues(new Uint8Array(12));
      const aad = makeAad(owner, name);
      const ct = await crypto.subtle.encrypt(
        { name: "AES-GCM", iv, additionalData: aad },
        derivedKey,
        encoder.encode(value)
      );
      const blob = new Uint8Array(12 + ct.byteLength);
      blob.set(iv, 0);
      blob.set(new Uint8Array(ct), 12);
      await storage.set(key, bytesToB64(blob));
    },

    async get(owner: string, name: string): Promise<string | undefined> {
      const key = makeKey(owner, name);
      const stored = await storage.get(key);
      if (stored === undefined) return undefined;

      try {
        const data = b64ToBytes(stored);
        if (data.length < 13) throw new Error("corrupt secret");
        const iv = data.subarray(0, 12);
        const ct = data.subarray(12);
        const aad = makeAad(owner, name);
        const plain = await crypto.subtle.decrypt(
          { name: "AES-GCM", iv, additionalData: aad },
          derivedKey,
          ct
        );
        return decoder.decode(plain);
      } catch (e) {
        throw new Error("Secret verification failed", { cause: e });
      }
    },

    async list(owner: string): Promise<string[]> {
      const prefix = SECRET_PREFIX + encodeStr(owner) + "|";
      const allKeys = await storage.keys();
      const names: string[] = [];
      for (const k of allKeys) {
        if (k.startsWith(prefix)) {
